def publication_panel() -> str:
    return """<section id='tracking' class='gwa-publications' hidden><style>#tracking{--gwa-publications-green:#215b48;--gwa-publications-paper:#fffef9;--gwa-publications-text:#173a35;--gwa-publications-border:#dce3d5;width:100%;max-width:100%;box-sizing:border-box;padding:16px;overflow-x:hidden;background:var(--gwa-publications-paper);color:var(--gwa-publications-text);font-family:inherit;line-height:1.45}#tracking[hidden]{display:none}#tracking *,#tracking *::before,#tracking *::after{box-sizing:border-box;min-width:0}#tracking [hidden]{display:none}#tracking .gwa-publications-head{border-bottom:1px solid var(--gwa-publications-border);margin:0 0 16px;padding:0 0 8px}#tracking .gwa-publications-tabs{display:flex;flex-wrap:wrap;gap:8px}#tracking .gwa-publications-tab{min-height:44px;padding:8px 14px;border:1px solid var(--gwa-publications-border);border-radius:6px;background:var(--gwa-publications-paper);color:var(--gwa-publications-text);font:inherit;cursor:pointer}#tracking .gwa-publications-tab[aria-current='page']{background:var(--gwa-publications-green);border-color:var(--gwa-publications-green);color:var(--gwa-publications-paper)}#tracking .gwa-publications-message{margin:0;padding:12px;border:1px solid var(--gwa-publications-border);border-radius:6px;background:var(--gwa-publications-paper)}#tracking .gwa-publications-status{min-height:1.45em;margin:0 0 12px;color:var(--gwa-publications-text)}#tracking .gwa-publications-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:0 0 24px}#tracking .gwa-publications-field{display:flex;min-width:0;flex-direction:column;gap:6px}#tracking .gwa-publications-field-wide{grid-column:1/-1}#tracking .gwa-publications-label{font-weight:600}#tracking .gwa-publications-control{width:100%;max-width:100%;min-height:44px;padding:8px 10px;border:1px solid var(--gwa-publications-border);border-radius:6px;background:var(--gwa-publications-paper);color:var(--gwa-publications-text);font:inherit}#tracking .gwa-publications-preview{margin:0;padding:10px;border:1px solid var(--gwa-publications-border);border-radius:6px;background:var(--gwa-publications-paper);overflow-wrap:anywhere;white-space:pre-wrap}#tracking .gwa-publications-check{display:flex;min-height:44px;align-items:flex-start;gap:10px;padding:8px 0}#tracking .gwa-publications-check input{width:20px;height:20px;margin:2px 0 0;flex:0 0 auto;accent-color:var(--gwa-publications-green)}#tracking .gwa-publications-submit{min-height:44px;padding:10px 16px;border:1px solid var(--gwa-publications-green);border-radius:6px;background:var(--gwa-publications-green);color:var(--gwa-publications-paper);font:inherit;font-weight:600;cursor:pointer}#tracking .gwa-publications-submit:disabled{cursor:wait;opacity:.7}#tracking .gwa-publications-error{grid-column:1/-1;margin:0;padding:10px 12px;border:1px solid #b42318;border-radius:6px;background:#fff4f2;color:#7a1b13;overflow-wrap:anywhere}#tracking .gwa-publications-register-wrap{display:grid;gap:10px}#tracking .gwa-publications-register-wrap h2{margin:0;font-size:1.1rem}#tracking .gwa-publications-register{display:grid;gap:10px;margin:0;padding:0;list-style:none}#tracking .gwa-publications-record{display:grid;gap:4px;padding:12px;border:1px solid var(--gwa-publications-border);border-radius:6px;background:var(--gwa-publications-paper);overflow-wrap:anywhere}#tracking .gwa-publications-record p{margin:0}#tracking .gwa-publications-corrected{display:inline-block;width:fit-content;margin:0 0 4px;padding:2px 8px;border:1px solid var(--gwa-publications-border);border-radius:999px;color:var(--gwa-publications-green);font-size:.875em;font-weight:600}#tracking .gwa-publications-empty{margin:0;color:var(--gwa-publications-text)}@media (max-width:375px){#tracking{padding:12px}#tracking .gwa-publications-tabs{flex-direction:column}#tracking .gwa-publications-tab{width:100%}#tracking .gwa-publications-form{grid-template-columns:minmax(0,1fr)}#tracking .gwa-publications-field-wide{grid-column:auto}}</style><header class='gwa-publications-head'><nav class='gwa-publications-tabs' aria-label='Vistas de publicaciones'><button type='button' id='publications-general' class='gwa-publications-tab' aria-current='page'>Publicaciones generales</button><button type='button' id='publications-directed' class='gwa-publications-tab'>Comunicaciones dirigidas</button></nav></header><div id='publications-no-campaign' class='gwa-publications-message' hidden>Selecciona una campaña en Campañas</div><div id='publications-content' hidden><p id='publications-status' class='gwa-publications-status' role='status' aria-live='polite'></p><form id='publication-form' class='gwa-publications-form' novalidate><div class='gwa-publications-field gwa-publications-field-wide'><label class='gwa-publications-label' for='publication-version'>Pieza publicada</label><select id='publication-version' name='version_id' class='gwa-publications-control' required><option value=''>Selecciona una versión</option></select><p id='publication-version-preview' class='gwa-publications-preview' hidden></p></div><div class='gwa-publications-field'><label class='gwa-publications-label' for='publication-channel'>Medio</label><select id='publication-channel' name='channel' class='gwa-publications-control' required><option value=''>Selecciona un medio</option><option value='linkedin'>LinkedIn</option><option value='web'>Web</option><option value='ad'>Anuncio</option><option value='other_public'>Otro medio público</option></select></div><div class='gwa-publications-field'><label class='gwa-publications-label' for='publication-occurred-at'>Fecha de publicación</label><input id='publication-occurred-at' name='occurred_at' class='gwa-publications-control' type='datetime-local' required></div><div class='gwa-publications-field'><label class='gwa-publications-label' for='publication-public-url'>Enlace público</label><input id='publication-public-url' name='public_url' class='gwa-publications-control' type='url' inputmode='url' autocomplete='url'></div><div class='gwa-publications-field'><label class='gwa-publications-label' for='publication-repeat-reason'>Motivo de repetición</label><input id='publication-repeat-reason' name='repeat_reason' class='gwa-publications-control' type='text'></div><div class='gwa-publications-field gwa-publications-field-wide'><label class='gwa-publications-check' for='publication-confirmed'><input id='publication-confirmed' name='confirmed' type='checkbox' required><span>Confirmo que esto se publicó fuera de la app</span></label></div><div class='gwa-publications-field gwa-publications-field-wide'><button id='publication-submit' class='gwa-publications-submit' type='submit'>Registrar publicación</button></div><p id='publication-error' class='gwa-publications-error' role='alert' hidden></p></form><section class='gwa-publications-register-wrap' aria-labelledby='publications-register-title'><h2 id='publications-register-title'>Registros de publicación</h2><ul id='publication-register' class='gwa-publications-register'></ul><p id='publications-empty' class='gwa-publications-empty' hidden>No hay publicaciones registradas.</p></section></div><script>(function(){'use strict';var root=document.getElementById('tracking');if(!root){return;}var noCampaign=document.getElementById('publications-no-campaign');var content=document.getElementById('publications-content');var status=document.getElementById('publications-status');var form=document.getElementById('publication-form');var versionSelect=document.getElementById('publication-version');var versionPreview=document.getElementById('publication-version-preview');var channelSelect=document.getElementById('publication-channel');var occurredAtInput=document.getElementById('publication-occurred-at');var publicUrlInput=document.getElementById('publication-public-url');var repeatReasonInput=document.getElementById('publication-repeat-reason');var confirmedInput=document.getElementById('publication-confirmed');var submitButton=document.getElementById('publication-submit');var errorBox=document.getElementById('publication-error');var register=document.getElementById('publication-register');var emptyRegister=document.getElementById('publications-empty');var generalButton=document.getElementById('publications-general');var directedButton=document.getElementById('publications-directed');var CHANNEL_LABELS={linkedin:'LinkedIn',web:'Web',ad:'Anuncio',other_public:'Otro medio público'};var versionsById=new Map();var pendingOperation=null;var busy=false;var loadSequence=0;var REGISTER_ERROR='No se pudo registrar la publicación. Inténtalo de nuevo.';function asText(value){return value===null||typeof value==='undefined'?'':String(value);}function currentCampaignId(){var value=window.gwaCampaignId;if(value===null||typeof value==='undefined'){return '';}return String(value).trim();}function pathFor(campaignId){return '/api/campaigns/'+encodeURIComponent(campaignId)+'/publications';}function setBusy(value){busy=value;submitButton.disabled=value;form.setAttribute('aria-busy',value?'true':'false');}function clearError(){errorBox.textContent='';errorBox.hidden=true;}function showError(message){errorBox.textContent=message;errorBox.hidden=false;}function versionLabel(version){var parts=[];if(version&&version.format!==null&&typeof version.format!=='undefined'&&String(version.format).trim()!==''){parts.push(String(version.format));}if(version&&version.variant!==null&&typeof version.variant!=='undefined'&&String(version.variant).trim()!==''){parts.push(String(version.variant));}if(version&&version.revision_no!==null&&typeof version.revision_no!=='undefined'&&String(version.revision_no).trim()!==''){parts.push('rev. '+String(version.revision_no));}return parts.length>0?parts.join(' · '):'Versión sin título';}function updatePreview(){var selected=versionsById.get(versionSelect.value);var body='';if(selected){if(selected.body_preview!==null&&typeof selected.body_preview!=='undefined'){body=String(selected.body_preview);}else if(selected.preview!==null&&typeof selected.preview!=='undefined'){body=String(selected.preview);}else if(selected.body!==null&&typeof selected.body!=='undefined'){body=String(selected.body);}}versionPreview.textContent=body;versionPreview.hidden=body==='';}function renderVersions(versions){var previous=versionSelect.value;versionsById.clear();versionSelect.textContent='';var placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='Selecciona una versión';versionSelect.appendChild(placeholder);var seen=new Set();versions.forEach(function(version){if(!version||version.id===null||typeof version.id==='undefined'){return;}var id=String(version.id);if(seen.has(id)){return;}seen.add(id);versionsById.set(id,version);var option=document.createElement('option');option.value=id;option.textContent=versionLabel(version);versionSelect.appendChild(option);});if(previous!==''&&versionsById.has(previous)){versionSelect.value=previous;}else{versionSelect.value='';}updatePreview();}function channelDisplay(value){var key=asText(value);if(Object.prototype.hasOwnProperty.call(CHANNEL_LABELS,key)){return CHANNEL_LABELS[key]+' ('+key+')';}return key===''?'—':key;}function renderRecords(records){var validRecords=records.filter(function(record){return record&&typeof record==='object';});var supersededIds=new Set();validRecords.forEach(function(record){if(record.supersedes_id===null||typeof record.supersedes_id==='undefined'){return;}var superseded=String(record.supersedes_id);if(superseded!==''){supersededIds.add(superseded);}});register.textContent='';emptyRegister.hidden=validRecords.length!==0;validRecords.forEach(function(record){var recordId=asText(record.id);var versionId=asText(record.content_version_id);var version=versionsById.get(versionId);var versionFormat='';if(version&&version.format!==null&&typeof version.format!=='undefined'){versionFormat=String(version.format);}else if(record.format!==null&&typeof record.format!=='undefined'){versionFormat=String(record.format);}else if(record.version_format!==null&&typeof record.version_format!=='undefined'){versionFormat=String(record.version_format);}var item=document.createElement('li');item.className='gwa-publications-record';if(recordId!==''){item.setAttribute('data-record-id',recordId);}if(supersededIds.has(recordId)){var corrected=document.createElement('span');corrected.className='gwa-publications-corrected';corrected.textContent='Registro corregido';item.appendChild(corrected);}var versionLine=document.createElement('p');var versionTitle=document.createElement('strong');versionTitle.textContent='Versión: ';var versionIdText=document.createElement('span');versionIdText.textContent=versionId===''?'—':versionId;var formatText=document.createElement('span');formatText.textContent=' · Formato: '+(versionFormat===''?'—':versionFormat);versionLine.appendChild(versionTitle);versionLine.appendChild(versionIdText);versionLine.appendChild(formatText);item.appendChild(versionLine);var channelLine=document.createElement('p');var channelTitle=document.createElement('strong');channelTitle.textContent='Medio: ';var channelText=document.createElement('span');channelText.textContent=channelDisplay(record.channel);channelLine.appendChild(channelTitle);channelLine.appendChild(channelText);item.appendChild(channelLine);var dateLine=document.createElement('p');var dateTitle=document.createElement('strong');dateTitle.textContent='Fecha: ';var rawDate=asText(record.occurred_at);var dateText=document.createElement('time');if(rawDate!==''){dateText.dateTime=rawDate;dateText.setAttribute('data-occurred-at',rawDate);}dateText.textContent=rawDate===''?'—':rawDate;dateLine.appendChild(dateTitle);dateLine.appendChild(dateText);item.appendChild(dateLine);register.appendChild(item);});}function showNoCampaign(){noCampaign.hidden=false;content.hidden=true;status.textContent='';clearError();}async function loadTracking(){var campaignId=currentCampaignId();if(campaignId===''){loadSequence+=1;showNoCampaign();return;}var sequence=++loadSequence;noCampaign.hidden=true;content.hidden=false;status.textContent='Cargando publicaciones…';clearError();try{var data=await window.gwaApi(pathFor(campaignId),'GET');if(sequence!==loadSequence||currentCampaignId()!==campaignId){return;}var result=data&&typeof data==='object'?data:{};renderVersions(Array.isArray(result.versions)?result.versions:[]);renderRecords(Array.isArray(result.records)?result.records:[]);status.textContent='';noCampaign.hidden=true;content.hidden=false;}catch(error){if(sequence!==loadSequence){return;}status.textContent='No se pudieron cargar las publicaciones.';noCampaign.hidden=true;content.hidden=false;}}function createOperationId(){if(typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function'){return crypto.randomUUID();}var values=new Uint8Array(16);if(typeof crypto!=='undefined'&&typeof crypto.getRandomValues==='function'){crypto.getRandomValues(values);}else{for(var index=0;index<values.length;index+=1){values[index]=Math.floor(Math.random()*256);}}values[6]=(values[6]&15)|64;values[8]=(values[8]&63)|128;var output='';for(var position=0;position<values.length;position+=1){if(position===4||position===6||position===8||position===10){output+='-';}output+=(values[position]+256).toString(16).slice(1);}return output;}async function submitPublication(){if(busy){return;}clearError();var versionId=asText(versionSelect.value);if(versionId===''){showError('Selecciona una pieza publicada.');versionSelect.focus();return;}if(!versionsById.has(versionId)){showError('Selecciona una pieza publicada válida.');versionSelect.focus();return;}var channel=asText(channelSelect.value);if(!Object.prototype.hasOwnProperty.call(CHANNEL_LABELS,channel)){showError('Selecciona un medio.');channelSelect.focus();return;}var rawDate=asText(occurredAtInput.value);if(rawDate===''){showError('Indica la fecha de publicación.');occurredAtInput.focus();return;}var occurredDate=new Date(rawDate);if(Number.isNaN(occurredDate.getTime())){showError('La fecha de publicación no es válida.');occurredAtInput.focus();return;}if(!confirmedInput.checked){showError('Confirma que la publicación se realizó fuera de la app.');confirmedInput.focus();return;}var occurredAt=occurredDate.toISOString();var publicUrl=asText(publicUrlInput.value).trim();var repeatReason=asText(repeatReasonInput.value).trim();publicUrl=publicUrl===''?null:publicUrl;repeatReason=repeatReason===''?null:repeatReason;var basePayload={version_id:versionId,channel:channel,occurred_at:occurredAt,confirmed:true,public_url:publicUrl,repeat_reason:repeatReason};var fingerprint=JSON.stringify(basePayload);var operationId;if(pendingOperation&&pendingOperation.fingerprint===fingerprint){operationId=pendingOperation.id;}else{operationId=createOperationId();pendingOperation={fingerprint:fingerprint,id:operationId};}var payload={version_id:versionId,channel:channel,occurred_at:occurredAt,operation_id:operationId,confirmed:true,public_url:publicUrl,repeat_reason:repeatReason};var campaignId=currentCampaignId();if(campaignId===''){showNoCampaign();return;}setBusy(true);try{await window.gwaApi(pathFor(campaignId),'POST',payload);pendingOperation=null;confirmedInput.checked=false;await loadTracking();}catch(error){showError(REGISTER_ERROR);}finally{setBusy(false);}}form.addEventListener('submit',function(event){event.preventDefault();void submitPublication();});versionSelect.addEventListener('change',updatePreview);versionSelect.addEventListener('input',updatePreview);generalButton.addEventListener('click',function(){if(root.hidden){document.dispatchEvent(new CustomEvent('gwa:show',{detail:'tracking'}));}});directedButton.addEventListener('click',function(){if(typeof window.gwaShowView==='function'){window.gwaShowView('directed');}});document.addEventListener('gwa:show',function(event){if(event&&event.detail==='tracking'){root.hidden=false;void loadTracking();}});if(!root.hidden){void loadTracking();}})();</script></section>"""